package io.baozhu.atlas.api;
import io.baozhu.atlas.service.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/pipelines") public class PipelineController { private final PipelineService pipelines; private final RunOrchestrator runs; public PipelineController(PipelineService p,RunOrchestrator r){pipelines=p;runs=r;} @GetMapping public List<PipelineResponse> list(){return pipelines.list();} @GetMapping("/{id}") public PipelineResponse get(@PathVariable Long id){return pipelines.get(id);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public PipelineResponse create(@Valid @RequestBody CreatePipelineRequest request){return pipelines.create(request);} @PostMapping("/{id}/runs") public RunResponse run(@PathVariable Long id,@RequestHeader("Idempotency-Key") String key){return runs.start(id,key);} }
